        return "";
    }

    string new_url = api_url;
    if (!new_url.empty() && new_url.back() != '/') {
        new_url += '/';
    }
    new_url += user_id;

    return new_url;
}

int main() {
    // Test case 1: API URL ends with slash
    assert(get_url_for_query("https://example.com/api/user/", "aBc123") == 
           "https://example.com/api/user/aBc123");

    // Test case 2: API URL does not end with slash
    assert(get_url_for_query("https://example.com/api/user", "aBc123") == 
           "https://example.com/api/user/aBc123");

    // Test case 3: Empty user ID
    assert(get_url_for_query("https://example.com/api/user/", "") == "");

    return 0;
}

